-- Para hacer las multas 
;with prestamos_sin_multa as (
    select
        p.id_prestamo,
        datediff(day, p.fecha_limite, p.fecha_devolucion) as dias_retraso,
        row_number() over (order by p.id_prestamo) as numero
    from dbo.Prestamo p
    where p.estado_prestamo = 'Vencido'
      and p.fecha_devolucion is not null
      and p.fecha_devolucion > p.fecha_limite
      and not exists (
          select 1
          from dbo.Multa m
          where m.id_prestamo = p.id_prestamo
      )
)
    id_prestamo,
    id_tarifa,
    dias_retraso,
    monto_total,
    estado_pago
)
select
    p.id_prestamo,
    case when p.numero % 2 = 0 then 1 else 2 end,
    p.dias_retraso,
    p.dias_retraso *
        case when p.numero % 2 = 0 then 0.25 else 0.75 end,
    case when p.numero % 3 = 0 then 'Pagada' else 'Pendiente' end
from prestamos_sin_multa p;


-- Verificar que esten los datos 
select count(*) as total_prestamos
from dbo.Prestamo;

select count(*) as total_multas
from dbo.Multa;
